  try { await ring(back); notified = true; }
  catch (e) { if (typeof log === "function") log("agent withdrawal: the queue was not rung", String(e?.message ?? e)); }
}
return ok({ notified, id: d.id, withdrawn: true, repeat: d.repeat === true });

